namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

public class Department
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Code { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS" },
        new() { Id = 2, Name = "Mathematics", Code = "MATH" },
        new() { Id = 3, Name = "Physics", Code = "PHYS" },
        new() { Id = 4, Name = "English", Code = "ENGL" },
        new() { Id = 5, Name = "History", Code = "HIST" },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming education.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm analysis. Prerequisite: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and competitive programming.", DepartmentId = 1, IsFeatured = false },
        new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming education.", DepartmentId = 1, IsFeatured = true },
        new() { Id = 4, Code = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim is an award-winning educator with research interests in applied mathematics and numerical analysis.", DepartmentId = 2, IsFeatured = true },
        new() { Id = 5, Code = "MATH 252", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor's research focuses on abstract algebra and its applications to cryptography.", DepartmentId = 2, IsFeatured = false },
        new() { Id = 6, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction for science and engineering majors.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Elena Vasquez", InstructorBio = "Dr. Vasquez is an experimental physicist with a passion for making physics accessible to all students.", DepartmentId = 3, IsFeatured = false },
        new() { Id = 7, Code = "PHYS 220", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Elena Vasquez", InstructorBio = "Dr. Vasquez is an experimental physicist with a passion for making physics accessible to all students.", DepartmentId = 3, IsFeatured = true },
        new() { Id = 8, Code = "ENGL 110", Title = "Academic Writing", Description = "Develop skills in argumentation, research, and clear expository prose. Required for all first-year students.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Prof. David Nguyen", InstructorBio = "Prof. Nguyen is a published author and writing consultant with expertise in rhetoric and composition.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 9, Code = "ENGL 250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Prof. Maria Santos", InstructorBio = "Prof. Santos specializes in 20th-century American fiction and has authored three critical studies.", DepartmentId = 4, IsFeatured = false },
        new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Richard Park", InstructorBio = "Dr. Park is a historian of ancient civilizations with extensive fieldwork experience in the Mediterranean.", DepartmentId = 5, IsFeatured = false },
    ];

    private readonly List<EnrollmentRequest> _enrollments = [];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request) => _enrollments.Add(request);
}

