        new() { Id = 5, Code = "MATH 252", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor's research focuses on abstract algebra and its applications to cryptography.", DepartmentId = 2, IsFeatured = false },
